export type VerificationTier = 0 | 1 | 2 | 3 | 4 | "E";
export type PrototypeLabel =
  | "PROTOTYPE-UNVERIFIED"
  | "SEEDED-OPEN-DATA"
  | "COMMUNITY-REPORTED"
  | "VERIFIED";

export interface FieldEvidence {
  protocol_version: string;
  verifier_role: "trained_verifier" | "peer" | "operator" | "importer" | "desk_reviewer";
  method: string;
  observed_at: string;
  photo_ids?: string[];
}

export type FieldValue =
  | string
  | number
  | boolean
  | string[]
  | number[][]
  | "unknown"
  | "UNKNOWN";

export interface FieldFact {
  value: FieldValue;
  unit?: "mm" | "m" | "kg" | "percent" | "degrees" | "ratio" | null;
  method?: string | null;
  observed_at?: string;
  source_id: string;
  licence: string;
  retrieved_at: string;
  tier: VerificationTier;
  source_name?: string;
  source_key?: string;
  raw?: string | number | null;
  derived?: boolean;
  tri_state_observation?: boolean;
  evidence?: FieldEvidence;
}

export interface Provenance {
  tier: VerificationTier;
  prototype_label?: PrototypeLabel;
  source_name: string;
  source_id: string;
  source_date: string;
  record_date: string;
  licence_id: string;
  retrieved_at: string;
  evidence?: FieldEvidence;
}

export interface CanonicalRecord {
  record_type: string;
  schema_version: string;
  id: string;
  record_status: "draft" | "in_review" | "published" | "stale_flagged" | "archived" | "disputed";
  publication_context: "canonical" | "prototype";
  example?: boolean;
  provenance: Provenance;
  facts?: Record<string, FieldFact>;
  imported_facts?: Record<string, FieldFact>;
}

